            document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('h2').forEach(h=>{if(h.textContent.trim()==='Sửa chữa / đề xuất')h.textContent='Đề xuất / thanh lý';const old=h.closest('div.rounded.border.bg-white.p-3');if(old&&(h.textContent.trim()==='Điều động / thu hồi'||h.textContent.trim()==='Đề xuất / thanh lý'))old.remove();});const map={IN:'Nhập',OUT:'Xuất',ADJUST:'Điều chỉnh',CREATE:'Thêm mới',UPDATE:'Cập nhật',DELETE:'Xóa',IMPORT:'Nhập dữ liệu',MOVEMENT:'Nhập / xuất',INCREASE:'Tăng',DECREASE:'Giảm',REPAIR:'Sửa chữa',RECALL:'Thu hồi / trả về kho',LIQUIDATION:'Thanh lý',PENDING:'Chờ duyệt',APPROVED:'Đã duyệt',REJECTED:'Từ chối',COMPLETED:'Đã hoàn thành',BROKEN:'Hỏng',REPAIRING:'Đang sửa chữa',NORMAL:'Bình thường'};const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())if(!['SCRIPT','STYLE'].includes(walker.currentNode.parentElement?.tagName))nodes.push(walker.currentNode);nodes.forEach(node=>{const value=node.textContent.trim();if(map[value])node.textContent=node.textContent.replace(value,map[value]);});});
