    <script>
    const initInventoryTransferUi = () => {
        const form = document.querySelector('form[action*="/dieu-dong"]');
        const source = form?.querySelector('select[name="from_classroom_id"]');
        if (!form || !source) return;
        if (form.dataset.transferUiReady === '1') return;
        form.dataset.transferUiReady = '1';
        ['asset_id', 'material_id', 'industry_filter', 'type_filter'].forEach(name => {
            form.querySelectorAll(`[name="${name}"]`).forEach(field => {
                const label = field.closest('label');
                if (label) label.remove();
                else field.closest('.ui-select-field, .instructor-select-field')?.remove();
            });
        });
        const assets = {{ \Illuminate\Support\Js::from($transferAssets) }};
        form.querySelectorAll('.transfer-asset-table').forEach(node => node.parentElement?.remove());
        const table = document.createElement('div');
        table.id = 'transfer-source-assets';
        table.className = 'md:col-span-2 rounded-lg border bg-slate-50 p-3';
        table.innerHTML = '<div class="mb-2 flex items-center justify-between gap-2"><b>Vật tư hiện có trong phòng nguồn</b><input type="search" class="transfer-search rounded border bg-white p-2 text-sm" placeholder="Tìm mã hoặc tên"></div><div class="transfer-rows"></div>';
        (form.querySelector('button[type="submit"]') || form.querySelector('button'))?.before(table);
        const render = () => {
            const query = table.querySelector('.transfer-search').value.toLowerCase().trim();
            const rows = assets.filter(item => Number(item.room) === Number(source.value) && Number(item.quantity) > 0 && (!query || `${item.code} ${item.name}`.toLowerCase().includes(query)));
            table.querySelector('.transfer-rows').innerHTML = !source.value
                ? '<p class="text-sm text-slate-500">Hãy chọn phòng nguồn để xem vật tư.</p>'
                : rows.length
                    ? `<table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-2">Chọn</th><th class="p-2">Mã</th><th class="p-2">Tên vật tư</th><th class="p-2">Số lượng hiện có</th><th class="p-2">Số lượng chuyển</th></tr></thead><tbody>${rows.map(item => `<tr class="border-b"><td class="p-2"><input type="checkbox" name="asset_ids[]" value="${item.id}" class="h-4 w-4"></td><td class="p-2">${item.code || ''}</td><td class="p-2">${item.name || ''}</td><td class="p-2">${item.quantity || 0} ${item.unit || ''}</td><td class="p-2"><input type="number" name="quantities[${item.id}]" min="1" max="${item.quantity || 1}" value="1" disabled class="w-20 rounded border p-1 text-sm" title="Số lượng chuyển"></td></tr>`).join('')}</tbody></table>`
                    : '<p class="text-sm text-slate-500">Phòng nguồn chưa có vật tư.</p>';
            table.querySelectorAll('input[name="asset_ids[]"]').forEach(check => {
                const quantity = check.closest('tr')?.querySelector(`input[name="quantities[${check.value}]"]`);
                check.addEventListener('change', () => { if (quantity) quantity.disabled = !check.checked; });
            });
        };
        if (typeof window.onTomChange === 'function') window.onTomChange(source, render);
        else source.addEventListener('change', render);
        table.querySelector('.transfer-search').addEventListener('input', render);
        form.addEventListener('submit', event => {
            if (!form.querySelector('input[name="asset_ids[]"]:checked')) {
                event.preventDefault();
                alert('Vui lòng chọn ít nhất một vật tư trong phòng nguồn.');
            }
        });
        render();
        setTimeout(render, 500);
    };
    document.addEventListener('DOMContentLoaded', initInventoryTransferUi);
    document.addEventListener('turbo:load', initInventoryTransferUi);
    </script>
    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const form = document.querySelector('form[action*="/dieu-dong"]');
        const destination = form?.querySelector('[name="to_classroom_id"]');
        const managingUnit = form?.querySelector('[name="using_unit"]');
        if (!form || !destination || !managingUnit) return;
        const rooms = {{ \Illuminate\Support\Js::from($transferRooms) }};
        const syncManagingUnit = () => {
            const room = rooms.find(item => String(item.id) === String(destination.value));
            managingUnit.value = room?.unit || '';
            managingUnit.placeholder = room?.unit ? 'Tự động theo phòng đích' : 'Phòng đích chưa có đơn vị quản lý';
        };
        if (typeof window.onTomChange === 'function') window.onTomChange(destination, syncManagingUnit);
        else destination.addEventListener('change', syncManagingUnit);
        syncManagingUnit();
    });
    </script>
    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const form = document.querySelector('form[action*="/dieu-dong"]');
        const field = form?.querySelector('[name="requesting_unit"]');
        if (!field) return;
        const label = field.closest('label');
        if (label?.firstChild) label.firstChild.textContent = 'Theo đề nghị của đồng chí Trưởng: *';
        field.placeholder = 'Nhập họ tên/chức vụ Trưởng đơn vị';
        const delivery = form.querySelector('[name="performing_unit"]');
        const deliveryLabel = delivery?.closest('label');
        if (deliveryLabel?.firstChild) deliveryLabel.firstChild.textContent = 'Đơn vị gọi giao *';
        const source = form.querySelector('[name="from_classroom_id"]');
        const rooms = {{ \Illuminate\Support\Js::from($transferRooms) }};
        const syncDelivery = () => {
            if (!delivery || delivery.dataset.userSelected === '1') return;
            const unit = rooms.find(item => String(item.id) === String(source?.value))?.unit || '';
            if (unit && delivery.tomselect) delivery.tomselect.setValue(unit, true); else if (unit) delivery.value = unit;
        };
        if (delivery) {
            if (typeof window.onTomChange === 'function') window.onTomChange(delivery, () => { delivery.dataset.userSelected = '1'; });
            else delivery.addEventListener('change', () => { delivery.dataset.userSelected = '1'; });
            if (typeof window.onTomChange === 'function') window.onTomChange(source, syncDelivery); else source?.addEventListener('change', syncDelivery);
            setTimeout(syncDelivery, 300); syncDelivery();
        }
    });
    </script>
    @endif
</div>
